// category.ts — the predicate category as edge data. Its objects are TERMS (entities, predicates, and
// whole cells); its morphisms are generated by the canonical predicate classes: specialization,
// converse, subject-projection, object-projection — each a bilattice homomorphism between predication
// fiber algebras A_p = L^(E×E). Here we record their INSTANCES as atomic edges so the path monad can
// compose them. An atom is shaped as the MPU's PathEdge {subject, predicate, object} with `predicate`
// carrying the GENERATOR KIND — so `saturate` (μ) accumulates the kind sequence, and that sequence IS the
// Curry-Howard proof term of the composite morphism.
import { type Term, termKey, cellOf } from "./term.ts";

/** The canonical predicate-category generator classes. */
export type Generator = "specialization" | "converse" | "subject-projection" | "object-projection";

/** The generator slot keys, in their canonical order. */
export const MORPHISM_KEYS: readonly Generator[] = ["specialization", "converse", "subject-projection", "object-projection"];

/** An atomic generator edge, in the MPU PathEdge shape so `saturate` composes it natively. The `predicate`
 * is the generator kind; composition accumulates these into the proof term. */
export interface Atom {
  readonly subject: Term;
  readonly predicate: Generator;
  readonly object: Term;
}

/** One hop of a proof: a generator kind and the term it lands on. */
export interface Step {
  readonly kind: Generator;
  readonly node: Term;
}

/** A witnessed route: a foundational root and the hops that prove the target (= the last hop's node). */
export interface Route {
  readonly root: Term;
  readonly steps: readonly Step[];
}

export interface StructureOptions {
  /** The predicate that signals a specialization (is-a / type) edge. Default "is-a". */
  readonly specializationPredicate?: Term;
}

const atomKey = (a: Atom): string => `${termKey(a.subject)}|${a.predicate}|${termKey(a.object)}`;

/** structureOf(cells) — fold a knowledge base of cells into the predicate category's atomic generator
 * edges. A specialization cell `(instance, is-a, type)` contributes the type→instance edge (the spine of
 * addressing, the /library/ chain). Every other (relational) cell `(s, p, o)` is itself a node, and
 * contributes its converse (the index swap), its subject-projection (collapse to the subject), and its
 * object-projection (collapse to the object) — the f* (pullback) direction of each generator. Deduplicated
 * by structural key, so equal structure yields equal edges (Yoneda). */
export function structureOf(cells: readonly { subject: Term; predicate: Term; object: Term }[], options: StructureOptions = {}): Atom[] {
  const specPredicate = options.specializationPredicate ?? "is-a";
  const specKey = termKey(specPredicate);
  const out: Atom[] = [];
  const seen = new Set<string>();
  const push = (atom: Atom): void => {
    const key = atomKey(atom);
    if (!seen.has(key)) { seen.add(key); out.push(atom); }
  };
  for (const cell of cells) {
    const { subject: s, predicate: p, object: o } = cell;
    if (termKey(p) === specKey) {
      // specialization: the type o specializes to the instance s (general → specific).
      push({ subject: o, predicate: "specialization", object: s });
      continue;
    }
    const node = cellOf(s, p, o);
    push({ subject: node, predicate: "converse", object: cellOf(o, p, s) });
    push({ subject: node, predicate: "subject-projection", object: s });
    push({ subject: node, predicate: "object-projection", object: o });
  }
  return out;
}
